import type { LessonExpansion } from '../types.ts';
import {chapter,reasoning,coding,cpp} from './basics-helpers.ts';
export const bronzeExpansions: Record<string, LessonExpansion> = {
'pensar-en-algoritmos':chapter('pensar-en-algoritmos',[
 ['Separa la historia de las cantidades','Un algoritmo empieza con una representación. Si preparas paquetes con dos lápices y un cuaderno, los datos relevantes son cantidades disponibles y consumo por paquete. El color de la mochila o el nombre de la escuela no cambian el cálculo, salvo que el enunciado les asigne una regla. Anota variables y unidades: lápices, cuadernos y paquetes no son intercambiables. Esta traducción evita combinar cantidades que significan cosas diferentes.'],
 ['Encuentra un límite que toda respuesta respete','Con 11 lápices puedes formar como máximo 5 paquetes, porque cada uno consume dos. Con 3 cuadernos puedes formar como máximo 3, porque cada paquete necesita uno. Cualquier solución debe respetar ambos límites, así que no puede superar el menor. Después comprueba que ese menor sí puede lograrse: tres paquetes usan seis lápices y tres cuadernos. Tenemos tanto una cota superior como una construcción que la alcanza.'],
 ['Del razonamiento al pseudocódigo','Escribe los pasos sin detalles del lenguaje: leer lápices y cuadernos; calcular grupos de dos lápices; tomar el menor entre ese número y cuadernos; escribirlo. Cada paso debe tener una razón. Solo después elige tipos y sintaxis. No necesitas simular paquete por paquete cuando la división cuenta exactamente el mismo proceso. Para otros problemas esa simulación puede ser un primer modelo útil antes de buscar una fórmula.'],
 ['Revisa la generalización','Prueba qué sucede cuando falta un recurso, cuando ambos se agotan juntos y cuando sobra mucho de uno. La fórmula debe responder a los tres sin condiciones improvisadas. También pregunta qué cambiaría si cada paquete necesitara tres lápices y dos cuadernos: ahora compararías lápices / 3 con cuadernos / 2. Esta variante comprueba que entendiste el argumento de recursos limitantes, no que memorizaste números particulares.']
 ],[reasoning('limites','Construcción y cota','Hay 17 lápices y 6 cuadernos; cada paquete usa 3 lápices y 2 cuadernos. Calcula el máximo y explica por separado por qué no puede ser mayor y por qué sí se puede alcanzar.',['Calcula cuántos paquetes permite cada recurso.','El menor límite debe poder construirse.'],'Los lápices permiten 5 paquetes y los cuadernos 3; por eso ninguna solución supera 3. Construir 3 usa 9 lápices y 6 cuadernos, disponibles en la entrada. La cota y la construcción coinciden, así que 3 es óptimo. Mencionar solo que «parece el menor» no muestra todavía ambas partes del argumento.'),coding('paquetes','Paquetes del taller','Entrada: l y c (0 ≤ l,c ≤ 1000000000), lápices y cuadernos. Cada paquete lleva 2 lápices y 1 cuaderno. Salida: máximo número de paquetes completos.',['Los lápices permiten l / 2 paquetes.','Los cuadernos permiten c; toma el menor.'],'Cada paquete exige ambos recursos. Por ello la respuesta no supera l / 2 ni c. El menor de esos dos valores puede construirse porque no requiere más de lo disponible de ninguno. Ese argumento demuestra el óptimo para cualquier entrada, incluidos recursos en cero. El programa usa división entera, una comparación y salida: tiempo y memoria O(1).',cpp('    long long l,c; cin >> l >> c;\n    long long paquetes=l/2;\n    if(c<paquetes) paquetes=c;\n    cout << paquetes << "\\n";'),[['11 3\n','3\n'],['0 8\n','0\n'],['8 100\n','4\n'],['10 5\n','5\n']])]),
'complejidad':chapter('complejidad',[
 ['El tamaño de entrada es una variable','Llamamos n a una cantidad que puede crecer, como estudiantes o elementos. Medir una ejecución para n = 10 no dice por sí solo qué ocurrirá con n = 100000. La complejidad describe cómo crece el trabajo al cambiar n. No pretende predecir segundos exactos: el equipo, lenguaje y operaciones concretas influyen. Sirve para descartar crecimientos que claramente exceden los límites y comparar enfoques antes de implementarlos.'],
 ['Suma recorridos, multiplica repeticiones anidadas','Dos ciclos completos consecutivos hacen aproximadamente 2n pasos y su crecimiento es O(n). Dos ciclos anidados donde ambos recorren n hacen aproximadamente n². Si el segundo comienza en i + 1, el total es (n − 1) + ... + 1 = n(n − 1)/2, que sigue siendo O(n²). Reducir a la mitad el trabajo puede ayudar, pero no cambia su orden de crecimiento.'],
 ['Un cálculo con números concretos','Para n = 1000 hay 499500 parejas distintas; para n = 100000 hay 4999950000. El aumento de cien veces en n produce aproximadamente diez mil veces más parejas. Esa comparación muestra por qué una enumeración aceptable para una entrada pequeña puede ser imposible en una grande. No uses una regla fija de operaciones por segundo como garantía: toma los límites como guía y deja margen para el costo de cada operación.'],
 ['Memoria y respuesta también tienen tamaño','Guardar n enteros de 64 bits necesita aproximadamente 8n bytes para los valores, además de la estructura que los contiene. Una tabla de n por n puede crecer demasiado aunque cada operación sea sencilla. Si solo piden contar parejas, una fórmula evita enumerarlas; si piden imprimir todas, la propia salida contiene O(n²) elementos. El objetivo exacto determina qué mejoras son posibles.']
 ],[reasoning('crecimiento','Compara dos recorridos','Para n = 1000, estima cuántas veces se ejecuta una instrucción en dos ciclos consecutivos de n vueltas y en dos ciclos anidados de n vueltas. Repite para n = 2000 y compara el factor de crecimiento.',['Suma cuando los ciclos son consecutivos.','Multiplica cuando cada vuelta exterior repite todo el interior.'],'Los consecutivos ejecutan 2000 y 4000 veces: al duplicar n, se duplica el trabajo. Los anidados ejecutan 1000000 y 4000000 veces: se multiplica por cuatro. Ambos pueden contener dos instrucciones for, pero su estructura determina crecimientos muy distintos. Contar palabras del código no sustituye contar ejecuciones.'),coding('parejas','Cuenta sin enumerar','Entrada: n (1 ≤ n ≤ 1000000000), número de participantes. Salida: número de parejas de participantes distintos, sin importar el orden. El resultado cabe en long long.',['Cada participante puede acompañarse de n − 1 personas.','Ese conteo incluye cada pareja dos veces.'],'Hay n(n − 1) elecciones ordenadas: primera y segunda persona. Cada pareja no ordenada aparece como (A,B) y (B,A), así que dividimos entre dos. El producto máximo es menor que 10 elevado a 18 y cabe en long long. Con n = 1 no existe ninguna pareja. La fórmula usa O(1) tiempo y memoria, mientras enumerar parejas costaría O(n²).',cpp('    long long n; cin >> n;\n    cout << n*(n-1)/2 << "\\n";'),[['4\n','6\n'],['1\n','0\n'],['1000000000\n','499999999500000000\n']])]),
'ordenamiento':chapter('ordenamiento',[
 ['Ordenar crea relaciones entre vecinos','Una lista desordenada obliga a buscar cada vez dónde está el menor. Al ordenar ascendentemente, cada elemento queda antes de los que son mayores o iguales. En [8,2,5,2], el orden es [2,2,5,8]. Las repeticiones no desaparecen: ordenar cambia posiciones, no contenido. Muchas tareas se simplifican porque el orden hace visibles extremos, grupos iguales o diferencias entre valores consecutivos.'],
 ['Qué hace sort y qué no conserva','sort(a.begin(), a.end()) ordena el intervalo completo de un vector según <. Su costo es O(n log n) comparaciones. Si necesitas devolver posiciones originales, guarda cada valor junto con su índice antes de ordenar. No esperes que los índices antiguos sigan describiendo las mismas personas después del cambio. Cuando hay valores iguales, sort no promete conservar su orden relativo; si importa, diseña un desempate o una estrategia apropiada.'],
 ['La posición k tiene una convención','Si el enunciado pide el tercer valor más pequeño contando desde uno, en el vector ordenado consultamos a[2]. Convertir k a k − 1 conecta ambas numeraciones. Con [2,2,5,8], el segundo valor es 2, no 5: se cuentan apariciones salvo que se pidan explícitamente valores distintos. Esta diferencia debe resolverse leyendo el contrato, no eliminando repeticiones por costumbre.'],
 ['Un empate con información original','Si registramos tiempos de Ana 12, Beto 8 y Carla 12, ordenar solo [12,8,12] no nos dice después cuál de los dos doces pertenecía a cada persona. Podemos guardar pares (tiempo, índiceOriginal): (12,0), (8,1), (12,2). Ordenados quedan (8,1), (12,0), (12,2), y así recuperamos nombres o posiciones. Si el problema pide el k-ésimo tiempo y nada más, esos índices no son necesarios. La representación debe conservar exactamente la información que la salida exige.'],
 ['Cuándo ordenar es más trabajo del necesario','Para obtener únicamente el mínimo, un recorrido lineal basta y evita reorganizar toda la lista. Para responder varias preguntas sobre posiciones por tamaño, ordenar puede compensar. La elección depende de lo que necesitas después. Explica qué propiedad aprovechas al ordenar y considera el costo total, incluida la lectura y cualquier estructura auxiliar para recuperar información original.']
 ],[reasoning('repetidos','Orden y posiciones','Ordena [7,3,7,1,3]. Indica el cuarto elemento más pequeño contando repeticiones y el segundo valor distinto. Explica por qué son preguntas diferentes.',['Conserva las cinco apariciones al ordenar.','Eliminar duplicados cambia la cantidad de posiciones.'],'La lista ordenada es [1,3,3,7,7]. El cuarto elemento es 7. Los valores distintos son [1,3,7], cuyo segundo es 3. La lista ordenada conserva cinco apariciones y la lista de valores distintos solo tres; el tercer elemento contando repeticiones es 3, mientras el tercer valor distinto es 7. El significado de k depende de si contamos apariciones o valores únicos.'),coding('posicion','El tiempo k de entrenamiento','Entrada: n y k (1 ≤ k ≤ n ≤ 100000), seguidos de n tiempos enteros entre 0 y 1000000000. Salida: el k-ésimo tiempo más pequeño, contando tiempos repetidos.',['Ordena sin borrar duplicados.','Accede a k − 1 después de ordenar.'],'El orden ascendente coloca exactamente los k − 1 elementos anteriores antes del elemento de índice k − 1. Por definición ese es el k-ésimo contando todas las apariciones. Los límites garantizan que el índice existe. Leemos y guardamos O(n) valores; ordenar requiere O(n log n) tiempo y la consulta final es constante.',cpp('    int n,k; cin >> n >> k;\n    vector<long long> a(n); for(auto &x:a) cin >> x;\n    sort(a.begin(),a.end());\n    cout << a[k-1] << "\\n";','iostream vector algorithm'),[['5 3\n7 3 7 1 3\n','3\n'],['1 1\n0\n','0\n'],['4 4\n9 2 5 2\n','9\n']])]),
'busqueda-exhaustiva':chapter('busqueda-exhaustiva',[
 ['Define exactamente una posibilidad','Si buscamos dos materiales distintos de una lista, una posibilidad es un par de posiciones i y j. Valores iguales pueden corresponder a materiales diferentes; lo que no debe repetirse es la posición. Elegimos i < j para representar cada pareja una sola vez. Antes de escribir ciclos, decide si importa el orden, si se permiten repeticiones y qué condición hace válida una posibilidad. Estas decisiones determinan el espacio de búsqueda.'],
 ['Separar generar, comprobar y mejorar','Primero generamos una pareja. Después calculamos su costo y comprobamos si respeta el presupuesto. Si es válida, comparamos su calidad con la mejor encontrada. Mantener estas tres tareas separadas permite revisar cada una. Una respuesta inicial como −1 puede representar «todavía no hay ninguna pareja válida» cuando los costos son no negativos; usar cero podría confundir ausencia con una compra válida de costo cero.'],
 ['Por qué revisar todo demuestra el óptimo','Toda solución permitida corresponde a alguna pareja i < j y los ciclos la visitan. Por lo tanto, también visitan una pareja óptima. Al conservar la mejor de las válidas, el resultado final no puede ser peor que esa óptima ni exceder lo permitido. El argumento depende de la cobertura completa; una selección de «parejas que parecen prometedoras» necesita otra prueba y ya no es una búsqueda exhaustiva simple.'],
 ['Verifica con un caso completamente enumerable','Para precios [1,4,4] y presupuesto 5, las parejas de índices son (0,1), (0,2) y (1,2), con costos 5,5 y 8. Las dos primeras son válidas, aunque tengan la misma suma. Si pedimos el mejor costo, la respuesta es 5; si pedimos cuántas parejas sirven, la respuesta es 2. Cambiar el acumulador de máximo a contador cambia el objetivo, pero no la enumeración. Esta separación ayuda a reutilizar una idea sin confundir qué se está calculando.'],
 ['Usa los límites para decidir','Hay n(n − 1)/2 parejas. Para n = 100 son 4950, una cantidad pequeña; para n = 200000 son casi veinte mil millones. No descartes la enumeración por parecer sencilla: para límites pequeños es clara y confiable. También puede servir como referencia para comprobar una solución más rápida en casos pequeños, siempre que ambas interpreten exactamente el mismo problema.']
 ],[reasoning('cobertura','Enumera sin repetir','Para cuatro objetos A,B,C,D, escribe todas las parejas distintas sin importar el orden. Explica qué perderías si solo revisaras parejas vecinas en la lista.',['Cada pareja tiene un primer índice menor.','Vecinos no cubre, por ejemplo, A con D.'],'Las parejas son AB, AC, AD, BC, BD y CD. Revisar solo AB, BC y CD omite AC, AD y BD, cualquiera de las cuales podría ser óptima según sus costos. El hecho de que dos objetos no estén juntos en la entrada no los vuelve inválidos. La enumeración completa necesita visitar cada i < j.'),coding('presupuesto','Dos materiales para el club','Entrada: n y b (2 ≤ n ≤ 200, 0 ≤ b ≤ 2000000000), seguidos de n precios entre 0 y 1000000000. Elige exactamente dos posiciones distintas. Salida: mayor suma que no supera b, o −1 si no existe pareja válida.',['Enumera i < j.','Actualiza la mejor suma solo si cabe en el presupuesto.'],'Los ciclos generan cada pareja de posiciones una vez. Para cada una calculamos la suma y, si no supera b, conservamos la mayor. Si ninguna es válida, el marcador −1 queda intacto. Precios repetidos son permitidos porque representan objetos distintos. El tiempo es O(n²) y la memoria O(n); con n ≤ 200 solo hay 19900 parejas.',cpp('    int n; long long b; cin >> n >> b;\n    vector<long long> a(n); for(auto &x:a) cin >> x;\n    long long mejor=-1;\n    for(int i=0;i<n;++i) for(int j=i+1;j<n;++j){\n        long long s=a[i]+a[j];\n        if(s<=b && s>mejor) mejor=s;\n    }\n    cout << mejor << "\\n";','iostream vector'),[['4 10\n2 6 5 9\n','8\n'],['2 3\n2 2\n','-1\n'],['3 0\n0 0 1\n','0\n'],['2 2000000000\n1000000000 1000000000\n','2000000000\n']])]),
'voraces':chapter('voraces',[
 ['Una elección local necesita una razón global','Un algoritmo voraz elige lo que parece mejor en el momento y continúa sin reconsiderar. Esa descripción no demuestra corrección. Para monedas de valores 1, 5 y 10, tomar primero dieces puede justificarse con intercambios; para monedas 1, 3 y 4, tomar la mayor falla en cantidad 6: 4 + 1 + 1 usa tres monedas y 3 + 3 usa dos. Siempre pregunta qué propiedad particular permite la elección.'],
 ['Intercambia una solución sin empeorarla','Con monedas 1,5,10, cualquier solución con cinco monedas de uno puede reemplazarlas por una de cinco y usar menos. Dos monedas de cinco se reemplazan por una de diez. Así, en una solución óptima hay menos de cinco unos y menos de dos cincos. El resto del valor debe estar en dieces. Esa estructura coincide exactamente con tomar tantas monedas grandes como sea posible.'],
 ['Del argumento a la operación','Para cantidad 28, elegimos dos dieces y queda 8; elegimos un cinco y quedan 3; finalmente tres unos. Son seis monedas. La división cuenta cuántas monedas de una denominación caben y el residuo conserva lo pendiente. No necesitamos restar una moneda por vuelta. La implementación es constante, pero lo que la vuelve correcta es el argumento de intercambio y las denominaciones específicas.'],
 ['Reconoce cuándo detener la intuición','Antes de aplicar una regla a otro problema, busca un caso pequeño que la refute. En selección de tareas, elegir la más corta, la primera que empieza o la de mejor premio pueden comportarse de forma diferente. Una solución voraz válida debe expresar qué objetivo optimiza y bajo qué restricciones. Encontrar un contraejemplo no es fracasar: elimina una hipótesis incorrecta antes de invertir tiempo en implementarla.']
 ],[reasoning('contraejemplo','La moneda más grande puede fallar','Con monedas ilimitadas de 1,3 y 4, compara el método que toma siempre la mayor posible para cantidad 6 con una mejor solución. ¿Qué afirmación queda refutada?',['Después de tomar 4 quedan 2.','Dos monedas de 3 también suman 6.'],'El método voraz produce 4 + 1 + 1, tres monedas. La solución 3 + 3 usa dos y es mejor. Queda refutada la afirmación de que elegir siempre la moneda mayor minimiza el número para cualquier sistema de denominaciones. No refuta sistemas particulares que sí admiten una prueba; debemos revisar las propiedades de cada uno.'),coding('monedas','Cambio con unos, cincos y dieces','Entrada: m (0 ≤ m ≤ 1000000000). Hay monedas ilimitadas de 1, 5 y 10. Salida: mínimo número de monedas para sumar exactamente m.',['Cuenta dieces y conserva el residuo.','Después cuenta cincos y finalmente unos.'],'Una solución óptima no contiene diez unos ni dos cincos cuando pueden convertirse en un diez con menos monedas. Tampoco contiene cinco unos, porque un cinco los reemplaza. Por tanto toma m / 10 dieces, después (m % 10) / 5 cincos y finalmente m % 5 unos. El argumento depende de estas denominaciones. Tiempo y memoria O(1).',cpp('    long long m; cin >> m;\n    cout << m/10 + (m%10)/5 + m%5 << "\\n";'),[['28\n','6\n'],['0\n','0\n'],['5\n','1\n'],['1000000000\n','100000000\n']])]),
'usaco-bronze-time-comp':chapter('usaco-bronze-time-comp',[
 ['No todos los ciclos anidados son iguales','Si para cada i entre 1 y n visitas i,2i,3i,... hasta n, el ciclo interior ejecuta aproximadamente n/i vueltas. El total es n/1 + n/2 + ... + n/n, de crecimiento O(n log n). No basta ver dos for y afirmar O(n²): sus límites importan. Puedes obtener una cota cuadrática válida, pero demasiado floja para explicar por qué el algoritmo funciona con entradas mayores.'],
 ['Agrupar ayuda a contar','Los términos con i entre 1 y 2 aportan a lo sumo una cantidad proporcional a n; los que están entre 2 y 4 también, y así por bloques que duplican sus límites. Hay aproximadamente log₂ n bloques. Esta es una manera intuitiva de entender el costo n log n sin calcular cada término de la suma armónica. Las constantes y el extremo exacto no cambian el crecimiento.'],
 ['Relaciona costo con el objetivo','A veces el número de resultados que necesitas producir ya impone un costo mínimo. Imprimir todos los subconjuntos de n elementos requiere al menos visitar 2ⁿ resultados. En cambio, si solo piden cuántos hay, puedes calcular una potencia. Antes de buscar una optimización, pregunta si estás haciendo trabajo que el problema realmente solicita o si lo generaste por una representación innecesariamente detallada.']
 ],[reasoning('sumatoria','Cuenta las visitas para cinco','Para n = 5, enumera los múltiplos visitados por i = 1,2,3,4,5. Suma las cantidades y explica por qué no hay 25 visitas.',['Para cada i, se visitan floor(n/i) números.','El salto del interior cambia con i.'],'Para i = 1 visitamos 1,2,3,4,5: cinco. Para 2, visitamos 2,4: dos. Para 3,4 y 5 visitamos uno cada vez. El total es 10. Los ciclos interiores no tienen todos longitud n; el salto i reduce sus vueltas. Contar 5 × 5 ignoraría esa dependencia.'),coding('visitas','Cuenta un recorrido de múltiplos','Entrada: n (1 ≤ n ≤ 1000000). Para cada i entre 1 y n se visitarían i,2i,3i,... hasta n. Salida: total de visitas contando repeticiones entre diferentes i. Puedes sumar n / i sin ejecutar cada visita.',['Para un i fijo hay n / i múltiplos.','Suma esa cantidad para todos los i.'],'El múltiplo k × i cabe exactamente cuando k ≤ n/i. Por eso el ciclo interior tendría floor(n/i) vueltas. Sumarlas con un solo ciclo produce el mismo conteo sin visitar cada múltiplo. La implementación tarda O(n) y usa O(1) memoria, mientras la simulación directa cuesta O(n log n). Usamos long long para el total.',cpp('    int n; cin >> n;\n    long long total=0;\n    for(int i=1;i<=n;++i) total += n/i;\n    cout << total << "\\n";'),[['5\n','10\n'],['1\n','1\n'],['10\n','27\n']])]),
'usaco-bronze-intro-ds':chapter('usaco-bronze-intro-ds',[
 ['La estructura depende de las preguntas','Un vector conserva posiciones y permite acceder por índice en O(1). Una tabla de frecuencias responde cuántas veces aparece cada valor cuando el universo de valores es pequeño. Una pila recuerda el último elemento añadido y una cola el primero pendiente. No son nombres intercambiables: elige la estructura que representa la información que necesitas consultar y actualizar. Para una suma simple puede bastar una sola variable.'],
 ['Valores como índices de una frecuencia','Si todos los valores están entre 0 y 100, un vector de 101 contadores puede guardar frecuencia[x]. Al leer 7,2,7, incrementamos frecuencia[7], luego frecuencia[2], y otra vez frecuencia[7]. Al final sabemos que 7 aparece dos veces y 2 una. La posición representa un valor posible, no una posición de la entrada; esta distinción evita mezclar el índice del recorrido con el dato que debe contarse.'],
 ['Tamaño, inicialización y empates','vector<int> frecuencia(101,0) deja todos los contadores en cero. Para encontrar el valor más frecuente podemos recorrer valores en orden y cambiar el ganador solo cuando aparece una frecuencia mayor. Así conservamos el menor en caso de empate. Si los valores fueran enormes o negativos sin un rango pequeño, una tabla directa desperdiciaría memoria o no admitiría índices válidos; más adelante usarás diccionarios o compresión.']
 ],[reasoning('frecuencias','Posición y valor no son lo mismo','Para la entrada [4,1,4,2,1,4], escribe las frecuencias de 1,2 y 4. Explica qué significa frecuencia[4] y por qué no es lo mismo que el elemento de índice 4 de la lista original.',['La tabla usa valores posibles como posiciones.','La lista original cuenta desde índice cero.'],'Las frecuencias son 2 para 1, 1 para 2 y 3 para 4. frecuencia[4] representa cuántas apariciones del valor cuatro hubo. En la lista original, el elemento de índice 4 es 1, porque es el quinto dato. Ambas estructuras usan índices, pero esos índices representan objetos diferentes y deben interpretarse según su contrato.'),coding('moda','Valor más frecuente','Entrada: n (1 ≤ n ≤ 100000), seguido de n enteros entre 0 y 100. Salida: el valor más frecuente; en empate, el menor.',['Usa 101 contadores.','Recorre valores de menor a mayor y reemplaza el ganador solo con una frecuencia estrictamente mayor.'],'La tabla cuenta cada aparición en la posición del valor. Después recorremos 0 hasta 100. Cuando una frecuencia supera la del ganador lo actualizamos; al usar > y recorrer en orden, una igualdad conserva el valor menor. El tiempo es O(n + 101) y la memoria adicional O(101), independiente de la longitud de la lista.',cpp('    int n; cin >> n;\n    vector<int> f(101,0);\n    for(int i=0;i<n;++i){ int x; cin >> x; ++f[x]; }\n    int mejor=0;\n    for(int x=1;x<=100;++x) if(f[x]>f[mejor]) mejor=x;\n    cout << mejor << "\\n";','iostream vector'),[['6\n4 1 4 2 1 4\n','4\n'],['4\n7 2 7 2\n','2\n'],['1\n100\n','100\n'],['3\n0 0 1\n','0\n']])]),
'usaco-bronze-simulation':chapter('usaco-bronze-simulation',[
 ['Especifica cada transición','Una simulación necesita estado inicial, eventos y reglas para pasar al estado siguiente. En una alcancía, el saldo basta para decidir si se puede retirar una cantidad. Un depósito siempre suma; un retiro solo resta cuando hay fondos. Es importante definir qué pasa si no alcanza: rechazar el retiro no es permitir saldo negativo ni retirar parcialmente. Las tres reglas producen procesos distintos aunque compartan la misma historia.'],
 ['Una tabla revela el orden','Desde saldo 10, retirar 7 deja 3; depositar 2 deja 5; retirar 6 se rechaza y conserva 5. Si comprobaras los fondos después de restar, necesitarías deshacer el cambio correctamente; es más claro comprobar antes. Para cambios simultáneos, en cambio, guarda el estado anterior y calcula el nuevo sin mezclar tiempos. Siempre pregunta si el enunciado describe una secuencia o una actualización simultánea.'],
 ['Demuestra el estado por pasos','Antes del primer evento, el saldo coincide con la condición inicial. Si antes de un evento es correcto, aplicar exactamente su regla produce el saldo correcto del siguiente paso. Repetir ese argumento demuestra toda la secuencia. El tiempo es proporcional a la cantidad de eventos si cada transición cuesta O(1). Si hay demasiados eventos para recorrerlos, necesitarás agruparlos o descubrir un patrón, pero primero define bien la simulación pequeña.']
 ],[reasoning('orden','Retiros rechazados','Empieza con saldo 8. Procesa R 10, D 5, R 8, R 5, donde D deposita y R retira solo si alcanza. Escribe el saldo después de cada evento.',['Un retiro rechazado deja el saldo igual.','Cada comprobación usa el saldo actual.'],'Los saldos son 8, 13, 5 y 0. El primer retiro se rechaza porque 8 < 10. El depósito lleva a 13; retirar 8 deja 5 y retirar exactamente 5 es válido. Este caso prueba rechazo, depósito, retiro normal e igualdad, que suele distinguir >= de >.'),coding('alcancia','La alcancía del equipo','Entrada: n y s (0 ≤ n ≤ 100000, 0 ≤ s ≤ 1000000000). Luego n líneas con D x o R x, donde 0 ≤ x ≤ 1000000000. D deposita x; R retira x solo si hay saldo suficiente y, si no, no cambia nada. Salida: saldo final.',['Mantén un único saldo de tipo long long.','Para R comprueba saldo >= x antes de restar.'],'Procesamos los eventos en orden. El saldo inicial es s; cada depósito suma y cada retiro permitido resta. Si un retiro no alcanza, el estado se conserva. Por inducción sobre eventos, el saldo siempre coincide con las reglas. La suma de depósitos puede superar int, así que usamos long long. Tiempo O(n), memoria adicional O(1).',cpp('    int n; long long saldo; cin >> n >> saldo;\n    for(int i=0;i<n;++i){\n        char tipo; long long x; cin >> tipo >> x;\n        if(tipo==\'D\') saldo+=x;\n        else if(saldo>=x) saldo-=x;\n    }\n    cout << saldo << "\\n";'),[['3 10\nR 7\nD 2\nR 6\n','5\n'],['0 0\n','0\n'],['4 8\nR 10\nD 5\nR 8\nR 5\n','0\n'],['2 1000000000\nD 1000000000\nD 1000000000\n','3000000000\n']])]),
'usaco-bronze-intro-complete':chapter('usaco-bronze-intro-complete',[
 ['Un espacio de búsqueda sin huecos','Para elegir tres posiciones distintas sin importar el orden, imponemos i < j < k. Los ciclos comienzan j en i + 1 y k en j + 1. Cada terna tiene un único orden creciente de índices, así que aparece exactamente una vez. Si los valores se repiten, las posiciones todavía pueden formar elecciones distintas. Define qué cuenta como una respuesta antes de intentar evitar duplicados.'],
 ['Comprueba restricciones después de generar','Supón que buscamos ternas cuya suma es un objetivo. La generación garantiza índices diferentes; la comprobación de suma decide si esa terna sirve. No necesitas que cada ciclo conozca todas las reglas: separar restricciones estructurales de condiciones del problema facilita demostrar cobertura. Para n = 4 solo hay cuatro ternas; puedes listarlas y compararlas con la ejecución para revisar límites de los ciclos.'],
 ['Cuenta antes de elegir el método','La cantidad de ternas es n(n − 1)(n − 2)/6, aproximadamente n³/6. Para n = 100 hay 161700, una cantidad razonable para operaciones sencillas. Para n = 10000, no. Una enumeración simple y correcta es una excelente solución cuando los límites la permiten. Si necesitas optimizar, la versión exhaustiva puede convertirse en un verificador de entradas pequeñas.']
 ],[reasoning('ternas-por-posicion','¿Qué se está contando?','En la lista [1,1,1,1], ¿cuántas ternas de posiciones distintas suman 3? ¿Cambiaría si se pidieran ternas de valores distintas sin considerar posiciones?',['Elige qué posición queda fuera.','Todas las ternas tienen los mismos valores.'],'Hay cuatro ternas de posiciones: cada una excluye una de las cuatro posiciones. Todas suman 3. Si contáramos combinaciones de valores sin distinguir posiciones, solo habría la combinación (1,1,1). La frase «posiciones distintas» define el objeto contado; eliminar valores repetidos cambiaría el problema.'),coding('ternas','Tres participantes suman el objetivo','Entrada: n y t (3 ≤ n ≤ 100, −3000000000 ≤ t ≤ 3000000000), seguidos de n enteros entre −1000000000 y 1000000000. Salida: número de ternas de posiciones i < j < k cuya suma es t.',['Usa tres ciclos con comienzos crecientes.','Conserva las posiciones aunque sus valores coincidan.'],'Cada terna válida tiene una única ordenación creciente de índices, visitada por los ciclos. La comparación de suma la cuenta si y solo si alcanza t. No se generan índices iguales ni permutaciones repetidas. Usamos long long para sumas y objetivo. El tiempo es O(n³) y la memoria O(n); con cien datos hay 161700 ternas.',cpp('    int n; long long t; cin >> n >> t;\n    vector<long long>a(n);for(auto &x:a)cin>>x;\n    long long total=0;\n    for(int i=0;i<n;++i) for(int j=i+1;j<n;++j) for(int k=j+1;k<n;++k)\n        if(a[i]+a[j]+a[k]==t) ++total;\n    cout << total << "\\n";','iostream vector'),[['5 6\n1 2 3 4 5\n','1\n'],['4 3\n1 1 1 1\n','4\n'],['3 0\n-1 0 1\n','1\n'],['3 10\n1 2 3\n','0\n']])]),
'usaco-bronze-complete-rec':chapter('usaco-bronze-complete-rec',[
 ['Una decisión por posición','Para generar subconjuntos, en la posición i decidimos excluir o incluir ese elemento. Después avanzamos a i + 1. Cuando i llega a n, todas las decisiones están tomadas y tenemos un subconjunto completo. El caso base debe regresar sin seguir llamando; de otro modo accederíamos fuera de la lista. La recursión representa un árbol binario de decisiones, no una operación misteriosa que se resuelve sola.'],
 ['Traza el árbol con dos elementos','Con [2,5], las decisiones generan vacío con suma 0, solo 5 con suma 5, solo 2 con suma 2 y ambos con suma 7, según el orden de ramas. Cada subconjunto corresponde a una secuencia única de incluir o excluir. Para permutaciones la decisión es diferente: eliges cuál elemento todavía no usado va en la siguiente posición, lo marcas y desmarcas al regresar. Confundir ambos árboles produce repeticiones o elementos faltantes.'],
 ['Estado y costo de regresar','Puedes pasar la suma acumulada por valor: cada llamada recibe su propio dato y no necesita deshacerlo manualmente. Si modificas un vector compartido al incluir un elemento, sí debes quitarlo antes de explorar la siguiente rama. Hay 2ⁿ subconjuntos y O(2ⁿ) nodos en este árbol; la profundidad es n. La memoria adicional de llamadas es O(n), sin contar guardar todos los resultados, que costaría mucho más.']
 ],[reasoning('arbol','Subconjuntos con repetidos','Dos posiciones contienen [3,3]. Enumera sus cuatro subconjuntos por posición y sus sumas. ¿Cuántos suman 3 y por qué no debes fusionar ambas posiciones?',['Cada posición tiene una decisión independiente.','Los valores iguales no identifican el mismo objeto.'],'Los subconjuntos son vacío, primera posición, segunda posición y ambas; sus sumas son 0,3,3 y 6. Dos suman 3. Aunque los valores coincidan, elegir la primera o la segunda posición representa decisiones diferentes. Si el problema pide subconjuntos de posiciones, deduplicar valores perdería respuestas legítimas.'),coding('subconjuntos','Subconjuntos con suma exacta','Entrada: n y t (0 ≤ n ≤ 20, −20000000 ≤ t ≤ 20000000), seguidos de n enteros entre −1000000 y 1000000. Salida: cantidad de subconjuntos de posiciones cuya suma es t. Incluye el subconjunto vacío.',['En cada posición explora excluir e incluir.','Solo compara con t al llegar al caso base i == n.'],'La recursión toma una decisión binaria por posición. Cada subconjunto determina exactamente esas decisiones, así que aparece una vez. En la hoja contamos uno si la suma coincide. El subconjunto vacío es la rama que excluye todo y suma cero. Valores negativos impiden descartar simplemente sumas que ya superaron t. Tiempo O(2ⁿ), profundidad y memoria adicional O(n).','#include <iostream>\n#include <vector>\nusing namespace std;\nvector<long long> a; long long objetivo;\nlong long contar(int i,long long suma){\n    if(i==(int)a.size()) return suma==objetivo;\n    return contar(i+1,suma)+contar(i+1,suma+a[i]);\n}\nint main(){\n    int n;cin>>n>>objetivo;a.resize(n);for(auto &x:a)cin>>x;\n    cout<<contar(0,0)<<"\\n";\n}\n',[['3 3\n1 2 3\n','2\n'],['0 0\n','1\n'],['2 3\n3 3\n','2\n'],['2 0\n-1 1\n','2\n']])]),
'usaco-bronze-intro-sorting':chapter('usaco-bronze-intro-sorting',[
 ['Ordenar puede reemplazar comparaciones lejanas','Para contar valores distintos sin ordenar, podrías comparar cada dato con todos los anteriores. Al ordenar, las apariciones de un mismo valor quedan juntas. Entonces basta detectar cuándo un valor cambia respecto al anterior. Esta es una transformación importante: invertir O(n log n) en ordenar permite un recorrido posterior sencillo y evita una búsqueda repetida O(n²).'],
 ['Sigue los grupos en una traza','La lista [4,2,4,1,2,2] se convierte en [1,2,2,2,4,4]. El primer elemento inicia un grupo. El segundo difiere y crea otro; los dos siguientes continúan el grupo de 2. El primer 4 crea el tercero y el último no agrega nada. Los cambios entre vecinos representan exactamente fronteras entre valores distintos. Si la lista estuviera vacía, no habría primer grupo: el caso debe tratarse explícitamente.'],
 ['Conserva información cuando sea necesaria','Esta técnica cuenta valores pero pierde el orden original. Si el problema necesita posiciones, guarda pares valor e índice o elige otra estructura. Ordenar no es una mejora universal; debe preservar todo lo relevante o permitir recuperarlo. Para comparar varios campos, define un orden estricto y desempates coherentes. Un comparador incorrecto puede invalidar la herramienta aunque el razonamiento sobre los grupos sea correcto.']
 ],[reasoning('grupos','Cuenta fronteras','Ordena [8,3,8,3,3,10] y señala cada posición donde inicia un valor distinto. Explica por qué el número de cambios entre vecinos es una unidad menor que el número de grupos en una lista no vacía.',['El primer grupo comienza sin una comparación anterior.','Cada cambio inicia exactamente otro grupo.'],'La lista es [3,3,3,8,8,10]. Los grupos comienzan en índices 0,3 y 5. Hay dos cambios entre vecinos, de 3 a 8 y de 8 a 10, pero tres grupos porque el primero ya existe al leer el primer elemento. Para una lista vacía la fórmula no se aplica sin un caso especial.'),coding('distintos','Valores distintos al ordenar','Entrada: n (0 ≤ n ≤ 100000), seguido de n enteros entre −1000000000 y 1000000000. Salida: cantidad de valores distintos. Resuelve ordenando y comparando vecinos.',['Si n = 0, la respuesta es cero.','Para cada posición, cuenta si es la primera o difiere de la anterior.'],'Después de ordenar, todas las apariciones de un valor forman un bloque. Contamos el inicio de cada bloque: índice cero o valor distinto al anterior. Esto asigna una unidad a cada valor y ninguna a sus repeticiones. La condición i == 0 se evalúa primero y evita consultar a[−1]. Tiempo O(n log n), memoria para datos O(n).',cpp('    int n;cin>>n;vector<long long>a(n);for(auto &x:a)cin>>x;\n    sort(a.begin(),a.end());\n    int distintos=0;\n    for(int i=0;i<n;++i) if(i==0 || a[i]!=a[i-1]) ++distintos;\n    cout<<distintos<<"\\n";','iostream vector algorithm'),[['6\n4 2 4 1 2 2\n','3\n'],['0\n','0\n'],['4\n7 7 7 7\n','1\n'],['3\n-1 0 1\n','3\n']])]),
'usaco-bronze-intro-sets':chapter('usaco-bronze-intro-sets',[
 ['Conjunto y diccionario responden preguntas diferentes','set guarda valores distintos y permite preguntar pertenencia; insertar dos veces el mismo valor no crea dos elementos. map asocia una clave con un dato, por ejemplo nombre con cantidad o número con frecuencia. Si necesitas recordar cuántas veces apareció un valor, un conjunto por sí solo pierde esa información. Escoge según las consultas, no solo según qué estructura recuerdas.'],
 ['Una consulta puede modificar un map','En map, escribir frecuencia[x] crea la clave con valor inicial si todavía no existe. Eso es cómodo al contar con ++frecuencia[x], pero puede sorprender si solo querías preguntar. Para consultar sin insertar puedes usar find. set::find y map::find devuelven end cuando no encuentran la clave. No confundas ese resultado con un valor numérico de la entrada ni intentes usarlo como un elemento válido.'],
 ['Orden y costo','Los contenedores ordenados estándar permiten operaciones habituales en O(log n). Sus claves aparecen en orden al recorrerlos. Las variantes unordered usan tablas hash y tienen costo esperado distinto, pero no garantizan el mismo orden. En Bronce, set y map suelen ofrecer una opción clara y suficiente. Si el universo de valores es muy pequeño, una tabla de frecuencias puede ser más sencilla y usar accesos directos O(1).']
 ],[reasoning('eleccion','¿Set o map?','Debes responder dos preguntas sobre [5,2,5,8,2,5]: cuántos valores distintos hay y cuántas veces aparece cada valor. Explica qué almacena un set y qué añade un map de frecuencias.',['Un set conserva una sola copia por valor.','El dato asociado a la clave puede ser el contador.'],'El set contiene {2,5,8}, así que informa que hay tres valores distintos, pero no conserva las repeticiones. El map puede guardar 2→2, 5→3 y 8→1. Ambos ordenan claves, pero solo el segundo conserva las cantidades necesarias para responder frecuencias. La estructura debe mantener toda la información que las consultas requieren.'),coding('repeticiones','Avisos de matrícula repetida','Entrada: n (0 ≤ n ≤ 100000), seguido de n identificadores enteros entre 0 y 1000000000. Salida: cuántas apariciones repiten un identificador visto anteriormente. Por ejemplo, tres apariciones del mismo identificador cuentan dos repeticiones.',['Guarda los identificadores ya vistos en un set.','Consulta antes de insertar o usa el resultado de insert.'],'Procesamos la secuencia en orden. Si un identificador ya pertenece al conjunto, su aparición es repetida; de lo contrario es la primera. Después lo insertamos para que las siguientes apariciones lo encuentren. Cada valor con frecuencia f contribuye f − 1. El tiempo es O(n log n) y la memoria O(n) en el peor caso.',cpp('    int n;cin>>n;set<long long> vistos;int repetidos=0;\n    for(int i=0;i<n;++i){\n        long long x;cin>>x;\n        if(vistos.find(x)!=vistos.end()) ++repetidos;\n        vistos.insert(x);\n    }\n    cout<<repetidos<<"\\n";','iostream set'),[['6\n5 2 5 8 2 5\n','3\n'],['0\n','0\n'],['3\n1 2 3\n','0\n'],['4\n7 7 7 7\n','3\n']])]),
'usaco-bronze-casework':chapter('usaco-bronze-casework',[
 ['Los casos deben cubrir todo sin contradicción','Un análisis por casos divide entradas según propiedades claras. Para dos intervalos sobre una recta, puede haber separación, contacto o superposición positiva. Las condiciones deben cubrir todas las posibilidades y dar respuestas compatibles en fronteras. Dibujar un caso de cada tipo ayuda más que escribir muchos if sin un mapa previo. Si dos casos se traslapan, revisa si producirían resultados diferentes para la misma entrada.'],
 ['Una fórmula puede reunir los casos','La intersección de intervalos [a,b] y [c,d] empieza en max(a,c) y termina en min(b,d). Su longitud es max(0, min(b,d) − max(a,c)). Si el final queda antes del inicio, no hay longitud común; si son iguales, solo se tocan y la longitud es cero. Esta fórmula resume los casos geométricos sin exigir enumerar todas las posibles posiciones relativas.'],
 ['No confundas longitud con puntos enteros','El intervalo [2,5] tiene longitud 3, pero contiene cuatro enteros: 2,3,4,5. Si el problema pide cantidad de posiciones enteras incluidas, la fórmula cambia y las fronteras importan de otra manera. Escribe las unidades de la respuesta y revisa una intersección que sea un solo punto. Una fórmula correcta para longitud puede ser incorrecta para conteo aunque ambos problemas dibujen los mismos intervalos.']
 ],[reasoning('fronteras','Longitud y cantidad','Los intervalos cerrados [1,4] y [4,7] se tocan en 4. ¿Cuál es la longitud de la intersección y cuántos puntos enteros contiene? Explica por qué no son la misma respuesta.',['Un solo punto no ocupa longitud positiva.','El punto 4 sí es un entero incluido.'],'La longitud es cero y la cantidad de puntos enteros es uno. La longitud mide distancia entre extremos; el conteo mide elementos discretos. Sumar uno a toda fórmula de intervalos sin preguntar qué se mide confunde ambos modelos. Este ejemplo de frontera obliga a precisar el significado de la salida.'),coding('intervalos','Tramo compartido','Entrada: a,b,c,d (−1000000000 ≤ a ≤ b ≤ 1000000000 y lo mismo para c ≤ d). Representan dos segmentos cerrados. Salida: longitud de su intersección; si solo se tocan o no se cruzan, escribe 0.',['El inicio común es el mayor de los inicios.','El final común es el menor de los finales.'],'Un punto pertenece a ambos segmentos si está después de ambos inicios y antes de ambos finales. Por eso la parte común va de max(a,c) a min(b,d). Cuando el extremo final es menor o igual al inicial, la longitud es cero; en otro caso es su diferencia. long long evita desbordar al restar extremos lejanos. Tiempo y memoria O(1).',cpp('    long long a,b,c,d;cin>>a>>b>>c>>d;\n    long long inicio=max(a,c), fin=min(b,d);\n    cout<<max(0LL,fin-inicio)<<"\\n";','iostream algorithm'),[['1 7 4 10\n','3\n'],['1 4 4 7\n','0\n'],['1 2 5 6\n','0\n'],['-1000000000 1000000000 -1000000000 1000000000\n','2000000000\n']])]),
'usaco-bronze-intro-greedy':chapter('usaco-bronze-intro-greedy',[
 ['Elige lo que deja más espacio para el futuro','Si varias actividades ocupan una sola sala y queremos aceptar el mayor número, una estrategia es tomar la que termina primero entre las disponibles. Terminar antes deja un tramo futuro al menos tan amplio como elegir otra que termine después. El argumento no depende de que esa actividad sea la más corta ni la primera que empieza. El criterio debe relacionarse con el recurso que limita las elecciones restantes: aquí, el tiempo disponible.'],
 ['Prueba de intercambio','Considera una solución óptima y su primera actividad. La actividad que termina antes puede sustituirla: empieza dentro del horario permitido y termina no después, por lo que no impide las actividades posteriores de esa solución. Conservamos la cantidad. Después de fijar esa primera elección, repetimos el argumento con las actividades que empiezan cuando la sala vuelve a estar libre. Así justificamos cada decisión sin enumerar todas las agendas.'],
 ['Las fronteras forman parte de la regla','Si una actividad termina a las 10 y otra empieza a las 10, este ejercicio permite ambas. Por eso la condición es inicio >= últimoFinal. Si el problema exigiera tiempo de limpieza, habría que incorporarlo. Ordena por final y usa un desempate coherente; el desempate no cambia el argumento cuando todos los intervalos tienen duración positiva y el criterio principal sigue siendo terminar lo antes posible.']
 ],[reasoning('criterio','La más corta no siempre basta','Hay actividades [0,3], [3,6] y [2,4]. Todas usan la misma sala. Si eliges primero la más corta, ¿cuántas puedes tomar? ¿Qué agenda obtiene más?',['La actividad [2,4] choca con las otras dos.','Dos intervalos que se tocan pueden coexistir aquí.'],'Elegir [2,4], de duración dos, impide tomar [0,3] y [3,6], por lo que deja solo una. La agenda [0,3] y [3,6] contiene dos. El ejemplo refuta elegir siempre la menor duración. Ordenar por final escoge [0,3] y conserva espacio para [3,6], alineando la decisión con la disponibilidad futura.'),coding('agenda','Una sala para muchos talleres','Entrada: n (0 ≤ n ≤ 100000), seguido de n parejas inicio,fin con 0 ≤ inicio < fin ≤ 1000000000. Salida: máximo número de actividades sin superposición. Se permite que una empiece exactamente cuando otra termina.',['Ordena por hora de finalización.','Acepta una actividad si empieza después o al mismo tiempo que el último final elegido.'],'Ordenamos por final y recorremos. Si una actividad cabe, la aceptamos: sustituir la primera actividad de una agenda óptima por la que termina antes no elimina opciones posteriores. Aplicar ese intercambio repetidamente demuestra el máximo. Inicializamos la sala libre en tiempo cero, compatible con todos los inicios. El tiempo es O(n log n) y la memoria O(n).',cpp('    int n;cin>>n;vector<pair<long long,long long>> a;\n    for(int i=0;i<n;++i){long long s,e;cin>>s>>e;a.push_back({e,s});}\n    sort(a.begin(),a.end());\n    long long libre=0;int total=0;\n    for(auto p:a) if(p.second>=libre){++total;libre=p.first;}\n    cout<<total<<"\\n";','iostream vector algorithm utility'),[['3\n0 3\n3 6\n2 4\n','2\n'],['0\n','0\n'],['3\n0 10\n1 2\n2 3\n','2\n'],['3\n1 5\n2 5\n3 5\n','1\n']])]),
'usaco-bronze-intro-graphs':chapter('usaco-bronze-intro-graphs',[
 ['Define qué representa una conexión','Un grafo tiene vértices y aristas. Si una arista representa una amistad mutua, conecta en ambos sentidos; si representa una calle de un solo sentido, la dirección importa. Una arista no necesita ser una línea dibujada de cierta forma: el dibujo ayuda, pero la lista de relaciones define el grafo. Los vértices pueden representar personas, salones o estados de un problema, no solo lugares físicos.'],
 ['Lista de adyacencia y grado','Para n vértices, vector<vector<int>> vecinos(n) guarda una lista por vértice. Una arista no dirigida u–v agrega v a vecinos[u] y u a vecinos[v]. El grado es la cantidad de aristas incidentes, que coincide con la longitud de la lista en un grafo simple. Cada arista aporta dos al total de grados; por eso su suma es 2m. Esa identidad sirve como comprobación rápida de la representación.'],
 ['Presencia de una arista no es alcanzabilidad','Que A no tenga una arista directa con C no significa que no pueda llegar: quizá existe A–B–C. El grado cuenta vecinos inmediatos, no todos los vértices alcanzables. Más adelante usarás BFS y DFS para explorar caminos. Aquí domina primero representación, índices y dirección. Si el enunciado permite lazos o aristas repetidas, revisa su significado; no asumas que todo grafo es simple.']
 ],[reasoning('grados-y-aristas','Comprueba un grafo pequeño','Hay vértices 1,2,3,4 y aristas no dirigidas 1–2, 2–3 y 2–4. Escribe el grado de cada vértice, suma los grados y explica por qué el resultado duplica el número de aristas.',['Cada arista toca dos extremos.','El vértice 2 conecta con los otros tres.'],'Los grados son 1,3,1 y 1; suman 6. Hay tres aristas y cada una se cuenta una vez en cada extremo, así que la suma es 2 × 3. El grado de 1 es uno aunque pueda llegar a otros vértices pasando por 2: grado y alcanzabilidad describen propiedades distintas.'),coding('grados','Conexiones del campus','Entrada: n,m (1 ≤ n ≤ 100000, 0 ≤ m ≤ 100000), luego m aristas u,v con 1 ≤ u,v ≤ n y u ≠ v. No hay aristas repetidas. El grafo es no dirigido. Salida: los grados de los vértices 1..n en una línea.',['Cada arista aumenta dos contadores.','Puedes guardar solo grados si no necesitas recorrer caminos.'],'Inicializamos un contador por vértice. Para cada arista incrementamos ambos extremos, porque pertenece a los dos. Al terminar, cada contador incluye exactamente las aristas incidentes a ese vértice. No necesitamos listas completas para esta consulta, aunque serían útiles para explorar vecinos. Tiempo O(n + m), memoria O(n).',cpp('    int n,m;cin>>n>>m;vector<int> grado(n,0);\n    for(int i=0;i<m;++i){int u,v;cin>>u>>v;++grado[u-1];++grado[v-1];}\n    for(int i=0;i<n;++i){if(i)cout<<" ";cout<<grado[i];}\n    cout<<"\\n";','iostream vector'),[['4 3\n1 2\n2 3\n2 4\n','1 3 1 1\n'],['1 0\n','0\n'],['3 1\n1 3\n','1 0 1\n']])]),
'usaco-bronze-rect-geo':chapter('usaco-bronze-rect-geo',[
 ['Representa un rectángulo con intervalos','Un rectángulo paralelo a los ejes se describe con x1,y1,x2,y2, donde x1 ≤ x2 y y1 ≤ y2. Su ancho es x2 − x1 y su alto y2 − y1; el área es su producto. No necesitas recorrer puntos del plano para medirlo. Coordenadas negativas son válidas: lo importante es la diferencia entre extremos, no su distancia individual al origen.'],
 ['La intersección ocurre en ambos ejes','Para que dos rectángulos compartan área, sus intervalos horizontales y verticales deben superponerse con longitud positiva. Calculamos ancho común como max(0, min(x2A,x2B) − max(x1A,x1B)) y de forma análoga el alto. El área común es ancho por alto. Si solo comparten un borde o un punto, alguna dimensión vale cero y el área común es cero.'],
 ['Traza ambas dimensiones','Considera A con esquinas (0,0) y (5,4), y B con (2,1) y (7,3). Horizontalmente comparten desde 2 hasta 5, un ancho de 3; verticalmente comparten desde 1 hasta 3, una altura de 2. El área común es 6. Que los intervalos de x se crucen no basta: si movemos B por encima de y = 4, el alto común se vuelve cero y desaparece la intersección de área. Las dos coordenadas deben comprobarse de forma independiente antes de multiplicar.'],
 ['Área cubierta y tamaño de las cuentas','La unión de dos rectángulos tiene área A + B − intersección, porque sumar ambos cuenta dos veces la zona común. No confundas unión con el rectángulo mínimo que los contiene: este puede incluir espacios no cubiertos. Usa long long antes de multiplicar diferencias. Una fórmula constante evita simular una cuadrícula enorme y funciona con coordenadas que no son pequeñas.']
 ],[reasoning('union','No confundas cobertura con envolvente','Los rectángulos son [0,0] a [2,2] y [4,0] a [6,2]. Calcula el área cubierta por ambos y el área del rectángulo mínimo que los contiene. Explica la diferencia.',['Hay un espacio horizontal sin cubrir.','La unión no rellena automáticamente el hueco.'],'Cada rectángulo tiene área 4 y no se superponen; el área cubierta es 8. La envolvente va de x = 0 a 6 y de y = 0 a 2, con área 12. Los cuatro metros cuadrados entre x = 2 y x = 4 pertenecen a la envolvente pero no a la unión. Elegir la fórmula exige identificar qué región pide el problema.'),coding('interseccion','Área común de dos patios','Entrada: ocho enteros x1,y1,x2,y2,x3,y3,x4,y4, cada uno entre −1000000000 y 1000000000. Se garantiza x1 ≤ x2, y1 ≤ y2, x3 ≤ x4, y3 ≤ y4. Salida: área de intersección de ambos rectángulos paralelos a los ejes.',['Calcula la intersección de los intervalos de x y de y.','Trunca las dimensiones negativas a cero y multiplica como long long.'],'Un punto pertenece a ambos rectángulos si sus dos coordenadas pertenecen a las intersecciones de sus respectivos intervalos. La región común es otro rectángulo, posiblemente degenerado. Su ancho y alto se calculan con máximo de inicios y mínimo de finales; el producto da el área. Las dimensiones máximas son 2000000000 y el área máxima 4000000000000000000 cabe en long long. Tiempo y memoria O(1).',cpp('    long long a,b,c,d,e,f,g,h;cin>>a>>b>>c>>d>>e>>f>>g>>h;\n    long long ancho=max(0LL,min(c,g)-max(a,e));\n    long long alto=max(0LL,min(d,h)-max(b,f));\n    cout<<ancho*alto<<"\\n";','iostream algorithm'),[['0 0 5 4 2 1 7 3\n','6\n'],['0 0 2 2 2 0 4 2\n','0\n'],['0 0 1 1 3 3 4 4\n','0\n'],['-1000000000 -1000000000 1000000000 1000000000 -1000000000 -1000000000 1000000000 1000000000\n','4000000000000000000\n']])]),
'usaco-bronze-ad-hoc':chapter('usaco-bronze-ad-hoc',[
 ['Busca qué no cambia','Un invariante es una propiedad que una operación conserva. Si una operación suma dos a un número, su paridad no cambia. Si mueve una ficha entre dos cajas, la suma total se conserva. Identificar esas propiedades puede descartar objetivos imposibles sin simular. Empieza con casos pequeños y pregunta qué tienen en común los estados alcanzables, pero después demuestra la propiedad usando la definición de cada operación.'],
 ['Necesario no siempre es suficiente','Que el total de fichas sea correcto puede ser necesario para alcanzar un estado, pero quizá las operaciones también restringen dónde pueden colocarse. Para demostrar posibilidad necesitas una construcción, no solo ausencia de una contradicción. En una recta donde cada paso mueve exactamente una unidad, llegar de 0 a x en k pasos exige |x| ≤ k y que k − |x| sea par. Las condiciones también bastan: avanza hacia x y usa los pasos sobrantes en parejas de ida y vuelta.'],
 ['De observar ejemplos a una prueba','Para x = 2 y k = 4, puedes avanzar dos veces y luego hacer derecha e izquierda. Para x = 2 y k = 3, la paridad impide terminar allí. El patrón observado sugiere la regla, pero la construcción y el argumento de paridad la justifican para entradas grandes. Los problemas ad hoc no significan «adivinar un truco»: requieren traducir operaciones en propiedades y comprobar cuidadosamente su alcance.']
 ],[reasoning('necesarias','Distancia y paridad','Desde 0 debes llegar a 3 usando exactamente 6 pasos de +1 o −1. La distancia cabe en seis pasos, pero ¿es posible? Explica qué propiedad falta revisar.',['Cada paso cambia la paridad de la posición.','Tras un número par de pasos terminas en una posición par.'],'No es posible. Aunque 3 ≤ 6, después de seis cambios de paridad la posición final debe ser par, mientras 3 es impar. Equivalentemente, 6 − 3 es impar y no puede gastarse en parejas de ida y vuelta. Revisar solo distancia detecta una condición necesaria, pero no suficiente.'),coding('pasos','Entrenator en la recta','Entrada: x y k (−1000000000 ≤ x ≤ 1000000000, 0 ≤ k ≤ 1000000000). Entrenator parte de 0 y cada paso cambia su posición en +1 o −1. Salida: SI si puede terminar en x después de exactamente k pasos, o NO en otro caso.',['La distancia mínima es |x|.','Los pasos sobrantes deben poder agruparse en pares de ida y vuelta.'],'Se necesitan al menos |x| pasos, así que si k es menor no alcanza. Al tomar |x| pasos hacia el objetivo, cualquier par adicional puede ser una ida y vuelta que no cambia el final. Por ello basta y es necesario que k − |x| sea par. La necesidad de paridad también se ve porque cada paso cambia la paridad de la posición. Tiempo y memoria O(1).',cpp('    long long x,k;cin>>x>>k;\n    long long distancia=x<0?-x:x;\n    cout<<((k>=distancia && (k-distancia)%2==0)?"SI":"NO")<<"\\n";'),[['2 4\n','SI\n'],['3 6\n','NO\n'],['0 0\n','SI\n'],['-5 3\n','NO\n'],['-5 7\n','SI\n']])]),
'usaco-bronze-bronze-conclusion':chapter('usaco-bronze-bronze-conclusion',[
 ['Resuelve sin que el título revele la herramienta','Un problema final debe obligarte a elegir entre simular, enumerar, ordenar, contar o buscar una propiedad. Empieza por límites y ejemplos antes de decidir un nombre de algoritmo. Si n es pequeño, una búsqueda exhaustiva puede ser suficiente; si los valores vienen de un universo corto, una frecuencia puede evitar trabajo repetido. La habilidad que buscas es justificar la elección según la entrada y la salida, no reconocer una palabra en el título.'],
 ['Una lista de evidencias para avanzar','Puedes explicar la representación, mostrar una traza, justificar cobertura o una elección, calcular costo y revisar fronteras. Si falta alguna pieza, sabes qué repasar. No necesitas resolver todos los problemas al primer intento. Conviene, en cambio, poder reconstruir una solución después de estudiarla y distinguir por qué un método similar fallaría bajo otras condiciones. La siguiente etapa construye sobre estos hábitos, además de introducir herramientas nuevas.'],
 ['Un ejercicio que combina decisiones','Para encontrar los dos tiempos más cercanos, podrías comparar todas las parejas. Ordenar permite revisar solo vecinos: si dos valores no son vecinos, alguno intermedio forma una diferencia no mayor con un extremo. Esta observación conecta ordenamiento y una prueba de suficiencia. No bastaría decir «los vecinos suelen ser cercanos»; el argumento explica por qué descartar las demás parejas no pierde el mínimo.']
 ],[reasoning('seleccion','Elige herramientas con límites','Un problema pide contar valores distintos. En una versión n ≤ 30; en otra n ≤ 200000; en otra todos los valores están entre 0 y 50. Propón métodos y explica por qué los límites influyen.',['Enumerar comparaciones puede bastar para treinta.','Un universo pequeño permite contadores directos.'],'Para treinta datos podemos comparar cada valor con los anteriores en O(n²), con una prueba de no contar duplicados. Para doscientos mil, ordenar y contar cambios o usar un conjunto evita el costo cuadrático. Si el universo es 0..50, una tabla de presencia de 51 posiciones da tiempo O(n + 51). No hay una estructura única ideal para todas las restricciones.'),coding('cercanos','Los tiempos más cercanos','Entrada: n (2 ≤ n ≤ 100000), seguido de n tiempos entre 0 y 1000000000. Salida: menor diferencia absoluta entre tiempos de dos posiciones distintas. Los tiempos repetidos son válidos y producen diferencia cero.',['Ordena los tiempos.','Basta comparar vecinos en el orden.'],'Después de ordenar, si una pareja mínima no es vecina, existe un valor intermedio. La diferencia entre ese intermedio y uno de los extremos no supera la diferencia de la pareja, de modo que alguna pareja vecina alcanza un mínimo. Recorremos esas diferencias y conservamos la menor. Ordenar cuesta O(n log n), revisar cuesta O(n) y guardamos O(n) datos.',cpp('    int n;cin>>n;vector<long long>a(n);for(auto &x:a)cin>>x;\n    sort(a.begin(),a.end());\n    long long mejor=a[1]-a[0];\n    for(int i=2;i<n;++i) mejor=min(mejor,a[i]-a[i-1]);\n    cout<<mejor<<"\\n";','iostream vector algorithm'),[['5\n12 5 20 9 30\n','3\n'],['2\n0 1000000000\n','1000000000\n'],['4\n7 2 7 15\n','0\n']])]),
};
